mapper.select:
SELECT f.id, f.platform, f.shop_id, s.name AS shop_name, f.platform_warehouse_id, f.platform_warehouse_name, f.platform_item_id, f.sku_code, f.quantity, f.synced_at FROM wms_fbo_inventory_snapshot f LEFT JOIN shop s ON s.id = f.shop_id WHERE f.tenant_id = #{tenantId}
AND f.platform = #{qo.platform}
AND f.shop_id = #{qo.shopId}
AND f.sku_code LIKE CONCAT('%', #{qo.skuCode}, '%')
AND f.platform_warehouse_name LIKE CONCAT('%', #{qo.platformWarehouseName}, '%')
ORDER BY f.quantity DESC, f.sku_code, f.platform_warehouse_name

SELECT sku_code AS skuCode, COALESCE(SUM(quantity), 0) AS quantity
FROM wms_fbo_inventory_snapshot
WHERE tenant_id = #{tenantId}

    AND sku_code IN
    #{sku}

GROUP BY sku_code
